sys_ui_action.script:
// bfd_ui_block_card_permanent — a permanently blocked card is a financial
// action, so bfd_CaseUtils.highValueApprovalRequired gates it. Agents raise an
// approval; team leads and app admins may authorise directly.
(function blockCardPermanentAction() {
    var TASK_TABLE = 'x_1755386_safetr_0_bfd_case_task';
    var utils = new bfd_CaseUtils();
    var engine = new bfd_TriageEngine();

    var disputed = parseFloat(current.getValue('disputed_amount') || '0');
    if (isNaN(disputed)) disputed = 0;

    var canAuthorise =
        gs.hasRole('x_1755386_safetr_0.bfd_team_lead') ||
        gs.hasRole('x_1755386_safetr_0.bfd_admin') ||
        gs.hasRole('admin');

    var needsApproval =
        (utils.highValueApprovalRequired(current) || disputed > utils.HIGH_VALUE_THRESHOLD) && !canAuthorise;

    if (needsApproval) {
        var approval = new GlideRecord(TASK_TABLE);
        approval.initialize();
        approval.setValue('case', current.getUniqueValue());
        approval.setValue('task_type', 'approval');
        approval.setValue('status', 'open');
        approval.setValue('priority', current.getValue('priority') || 'p2');
        approval.setValue(
            'outcome',
            'Approval requested for a PERMANENT card block (disputed amount ' + disputed + ').'
        );
        if (current.getValue('assigned_group')) approval.setValue('assigned_group', current.getValue('assigned_group'));
        var approvalDue = new GlideDateTime();
        approvalDue.addDaysLocalTime(1);
        approval.setValue('due_date', approvalDue.getValue());
        approval.insert();

        current.setValue('case_status', 'pending_approval');
        engine.logAiDecision(current, {
            note:
                'Agent ' +
                gs.getUserDisplayName() +
                ' requested a PERMANENT card block. Approval is required (high-value financial action); case moved to Pending approval.',
            finalDecision: 'permanent_block_pending_approval',
        });
        current.update();

        gs.addInfoMessage(
            'A permanent card block on this case is a high-value action and needs team lead approval. The case is now "Pending approval" and an Approval task has been raised — the block has NOT been applied yet.'
        );
        action.setRedirectURL(current);
        return;
    }

    var task = new GlideRecord(TASK_TABLE);
    task.initialize();
    task.setValue('case', current.getUniqueValue());
    task.setValue('task_type', 'card_block');
    task.setValue('status', 'complete');
    task.setValue('priority', current.getValue('priority') || 'p1');
    task.setValue('outcome', 'Permanent card block authorised and applied by ' + gs.getUserDisplayName() + '.');
    if (current.getValue('assigned_group')) task.setValue('assigned_group', current.getValue('assigned_group'));
    if (current.getValue('assigned_agent')) task.setValue('assigned_agent', current.getValue('assigned_agent'));
    task.setValue('due_date', new GlideDateTime().getValue());
    task.insert();

    current.setValue('card_action', 'permanent_block');
    engine.logAiDecision(current, {
        note: 'PERMANENT card block authorised and applied by ' + gs.getUserDisplayName() + '.',
        finalDecision: 'card_action=permanent_block',
    });
    current.update();

    gs.addInfoMessage(
        'Permanent card block applied. A completed "Card block" task has been added and the action is recorded in the audit trail.'
    );
    action.setRedirectURL(current);
})();
